-- « aboriculture » sai chính tả; đúng là « arboriculture » (radical latin arbor-).
update public.questions
   set payload = jsonb_set(payload, '{accepted}', '"arboriculture"')
 where id = 'mrh4vaysa3ptm6';

-- « rejète » là biến thể chỉnh lý 1990; « rejette » mới là dạng chuẩn. Nhận cả hai.
update public.questions
   set payload = jsonb_set(payload, '{accepted}', '"rejette|rejète"')
 where id = 'mrh4uuybxo82yr';

-- « insoucieuse » hiếm đến mức gần như không dùng; dạng thường là « insouciante ».
update public.questions
   set payload = jsonb_set(payload, '{accepted}', '"insouciante|insoucieuse"')
 where id = 'mrh5c6y9bnitt3';
